    def maximumScoreAfterOperations(self, edges, values):
        n = len(values)
        g = [[] for _ in range(n)]
        for a, b in edges:
            g[a].append(b)
            g[b].append(a)
        import sys
        sys.setrecursionlimit(10**6)
        def dfs(u, p):
            total = values[u]
            keep = values[u]
            for v in g[u]:
                if v != p:
                    b, t = dfs(v, u)
                    total += t
                    keep += b
            return max(total, keep), total
        return dfs(0, -1)[0]

