class Solution {
    public long maximumScoreAfterOperations(int[][] edges, int[] values) {
        int n = values.length;
        List<List<Integer>> g = new ArrayList<>();
        for (int i = 0; i < n; i++) g.add(new ArrayList<>());
        for (int[] e : edges) { g.get(e[0]).add(e[1]); g.get(e[1]).add(e[0]); }
        return dfs(0, -1, g, values)[0];
    }
    private long[] dfs(int u, int p, List<List<Integer>> g, int[] values) {
        long total = values[u], keep = values[u];
        for (int v : g.get(u)) if (v != p) {
            long[] r = dfs(v, u, g, values);
            total += r[1];
            keep += r[0];
        }
        return new long[]{Math.max(total, keep), total};
    }
}

