class Solution:
    def maximumScoreAfterOperations(self, edges, values):
        n = len(values)
        g = [[] for _ in range(n)]
        for a, b in edges:
            g[a].append(b); g[b].append(a)
        best = [0] * n
        total = values[:]
        stack = [(0, -1, False)]
        while stack:
            u, p, done = stack.pop()
            if done:
                keep = values[u]
                for v in g[u]:
                    if v != p:
                        keep += best[v]
                best[u] = max(total[u], keep)
            else:
                stack.append((u, p, True))
                for v in g[u]:
                    if v != p:
                        stack.append((v, u, False))
            if not done:
                pass
        # recompute totals bottom-up in same traversal style
        tot = values[:]
        order = []
        stack = [(0, -1)]
        while stack:
            u, p = stack.pop()
            order.append((u, p))
            for v in g[u]:
                if v != p:
                    stack.append((v, u))
        for u, p in reversed(order):
            for v in g[u]:
                if v != p:
                    tot[u] += tot[v]
        for u, p in reversed(order):
            keep = values[u]
            for v in g[u]:
                if v != p:
                    keep += best[v]
            best[u] = max(tot[u], keep)
        return best[0]

