        vector<long long> tot(values.begin(), values.end()), best(n);
        vector<pair<int,int>> order;
        vector<pair<int,int>> st{{0, -1}};
        while (!st.empty()) {
            auto [u, p] = st.back(); st.pop_back();
            order.push_back({u, p});
            for (int v : g[u]) if (v != p) st.push_back({v, u});
        }
        for (int i = n - 1; i >= 0; i--) {
            auto [u, p] = order[i];
            long long keep = values[u];
            for (int v : g[u]) if (v != p) { tot[u] += tot[v]; keep += best[v]; }
            best[u] = max(tot[u], keep);
        }
        return best[0];
    }
};

