class Solution {
    public long maximumScoreAfterOperations(int[][] edges, int[] values) {
        int n = values.length;
        List<List<Integer>> g = new ArrayList<>();
        for (int i = 0; i < n; i++) g.add(new ArrayList<>());
        for (int[] e : edges) { g.get(e[0]).add(e[1]); g.get(e[1]).add(e[0]); }
        long[] tot = new long[n];
        for (int i = 0; i < n; i++) tot[i] = values[i];
        long[] best = new long[n];
        List<int[]> order = new ArrayList<>();
        Deque<int[]> st = new ArrayDeque<>();
        st.push(new int[]{0, -1});
        while (!st.isEmpty()) {
            int[] cur = st.pop();
            order.add(cur);
            for (int v : g.get(cur[0])) if (v != cur[1]) st.push(new int[]{v, cur[0]});
        }
        for (int i = n - 1; i >= 0; i--) {
            int u = order.get(i)[0], p = order.get(i)[1];
            long keep = values[u];
            for (int v : g.get(u)) if (v != p) { tot[u] += tot[v]; keep += best[v]; }
            best[u] = Math.max(tot[u], keep);
        }
        return best[0];
    }
}

